insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-008$vn$, $vn$The Other Two Goals$vn$, $vn$La segunda meta es monitorear y analizar tu crédito para crear una estrategia y ayudarte a mejorar tu puntaje. Y la meta final sería brindarte educación sobre tus derechos como consumidor y bienestar financiero completo. ¿Tiene sentido?$vn$, array[]::text[], $vn$[{"tone": "", "text": "La segunda meta es monitorear y analizar tu crédito para crear una estrategia y ayudarte a mejorar tu puntaje. Y la meta final sería brindarte educación sobre tus derechos como consumidor y bienestar financiero completo. ¿Tiene sentido?"}]$vn$::jsonb, null, null, $vn$Repaso de las metas$vn$, 80, $vn$Lighter than the recap. These are supporting goals, not the headline. Do not give them more weight than the first one.$vn$, $vn$This covers more than just the debt.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-009$vn$, $vn$Creditor Example (Optional)$vn$, $vn$Tomemos tu cuenta de (acreedor) como ejemplo. Poco después de que esta cuenta llegue a un estado de atraso o falta de pago, (acreedor) va a vender tu cuenta a una compañía de cobranzas. Al hacerlo, (acreedor) obtiene un beneficio fiscal al registrar tu deuda como “incobrable” y “darla de baja”, mientras al mismo tiempo la vende a una compañía de cobranzas. (Acreedor) toma su dinero, sale de la situación y ha vendido tu cuenta por centavos por dólar al cobrador de deudas. ¡Ahora este cobrador está tratando de cobrarte la cantidad completa! Un negocio bastante bueno para ellos, especialmente cuando consideras que lo único que realmente compraron fue papel.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Tomemos tu cuenta de (acreedor) como ejemplo. Poco después de que esta cuenta llegue a un estado de atraso o falta de pago, (acreedor) va a vender tu cuenta a una compañía de cobranzas. Al hacerlo, (acreedor) obtiene un beneficio fiscal al registrar tu deuda como “incobrable” y “darla de baja”, mientras al mismo tiempo la vende a una compañía de cobranzas. (Acreedor) toma su dinero, sale de la situación y ha vendido tu cuenta por centavos por dólar al cobrador de deudas. ¡Ahora este cobrador está tratando de cobrarte la cantidad completa! Un negocio bastante bueno para ellos, especialmente cuando consideras que lo único que realmente compraron fue papel."}]$vn$::jsonb, null, $vn$EJEMPLO DE ACREEDOR SI NECESITAS ACLARAR MÁS$vn$, $vn$Repaso de las metas$vn$, 90, $vn$Only used when they need it. Build indignation on their behalf across the whole passage and land hard on "paper". Then stop and be ready to fill gaps.$vn$, $vn$The collector has no real claim on me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-010$vn$, $vn$Creditor Example, Part Two$vn$, $vn$Cuando compran tu deuda de (Acreedor), simplemente reciben una hoja de cálculo con tu información de contacto, número de cuenta y cuánto le debías a (acreedor). Su única meta es sacarte la mayor cantidad de dinero posible. Una vez que la compañía de cobranzas tiene tu información, vas a recibir una carta por correo diciendo que tomaron tu deuda y que están intentando cobrar en nombre de (acreedor). Sabemos que muchas veces eso no es cierto porque (acreedor) ya les vendió esa deuda, recibió su dinero y ya está fuera de la situación. Una vez que recibas esa carta, simplemente nos la envías y permites que nuestro equipo maneje el proceso de disputa por ti de la A a la Z. Bastante sencillo, ¿verdad?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Cuando compran tu deuda de (Acreedor), simplemente reciben una hoja de cálculo con tu información de contacto, número de cuenta y cuánto le debías a (acreedor). Su única meta es sacarte la mayor cantidad de dinero posible. Una vez que la compañía de cobranzas tiene tu información, vas a recibir una carta por correo diciendo que tomaron tu deuda y que están intentando cobrar en nombre de (acreedor). Sabemos que muchas veces eso no es cierto porque (acreedor) ya les vendió esa deuda, recibió su dinero y ya está fuera de la situación. Una vez que recibas esa carta, simplemente nos la envías y permites que nuestro equipo maneje el proceso de disputa por ti de la A a la Z. Bastante sencillo, ¿verdad?"}]$vn$::jsonb, null, $vn$ESPERA UNA RESPUESTA Y ESTÁ PREPARADO PARA ACLARAR CUALQUIER DUDA AQUÍ$vn$, null, 95, $vn$The pivot from indignation to instruction. "You simply forward it to us" is the whole point — everything before it exists to make that one action feel easy.$vn$, $vn$All I have to do is forward the letter.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Revisión de crédito$vn$), $vn$REVES-001$vn$, $vn$Pen And Paper$vn$, $vn$Ahora, todo el proceso es muy sencillo. El primer paso es que tú y yo revisemos juntos tu reporte de crédito para asegurarnos de que esté correcto. Vamos a revisar cada una de tus cuentas y su saldo, así que si puedes, por favor toma papel y pluma y avísame cuando estés listo.$vn$, array[$vn$PT$vn$,$vn$AC$vn$]::text[], $vn$[{"tone": "PT", "text": "Ahora, todo el proceso es muy sencillo."}, {"tone": "AC", "text": "El primer paso es que tú y yo revisemos juntos tu reporte de crédito para asegurarnos de que esté correcto. Vamos a revisar cada una de tus cuentas y su saldo, así que si puedes, por favor toma papel y pluma y avísame cuando estés listo."}]$vn$::jsonb, null, $vn$REVISAR REPORTE DE CRÉDITO — Habla de las cosas que benefician tu cierre... resalta cuentas al máximo y cuentas por encima del límite$vn$, null, 10, $vn$Plain and administrative at the start, then a clear instruction. Getting a pen in their hand is a small commitment that makes the next one easier.$vn$, $vn$We are doing this together, and I am participating.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Revisión de crédito$vn$), $vn$REVES-002$vn$, $vn$The Payment$vn$, $vn$Entonces, la gran noticia es que, basándonos en esta información, parece que tu nuevo pago con nosotros sería solamente de $XXX por XX Meses. ¿Cómo te suena?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Entonces, la gran noticia es que, basándonos en esta información, parece que tu nuevo pago con nosotros sería solamente de $XXX por XX Meses. ¿Cómo te suena?"}]$vn$::jsonb, null, null, null, 20, $vn$Say the number cleanly and do not rush past it. Then stop. The silence after a price is the single hardest thing to hold and the most important.$vn$, $vn$That is lower than I expected.$vn$, false, 'published');
